const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'KnowSelf'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Right side geometric accent blocks
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 0, w: 3.2, h: 5.625,
    fill: { color: "141414" }
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.4, y: 0.6, w: 2.0, h: 0.08,
    fill: { color: theme.accent }
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.2, y: 1.4, w: 1.2, h: 1.2,
    fill: { color: theme.secondary },
    transparency: 85
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.6, y: 3.2, w: 0.9, h: 0.9,
    fill: { color: theme.accent },
    transparency: 80
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.8, y: 2.6, w: 0.6, h: 0.6,
    fill: { color: theme.secondary },
    transparency: 70
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.2, y: 4.4, w: 1.5, h: 0.08,
    fill: { color: theme.accent }
  });

  // Gold accent line at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.7, y: 0.7, w: 0.6, h: 0.06,
    fill: { color: theme.accent }
  });

  // Title: KnowSelf
  slide.addText("KnowSelf", {
    x: 0.7, y: 1.0, w: 5.8, h: 1.2,
    fontSize: 64, fontFace: "Georgia",
    color: "FFFFFF", bold: true,
    align: "left", valign: "top"
  });

  // Subtitle
  slide.addText("Teaching LLM Agents When to Think,\nReflect, or Seek Knowledge", {
    x: 0.7, y: 2.2, w: 5.8, h: 1.2,
    fontSize: 24, fontFace: "Calibri",
    color: theme.accent, bold: false,
    align: "left", valign: "top",
    lineSpacingMultiple: 1.3
  });

  // Description
  slide.addText("Agentic Knowledgeable Self-Awareness\nfor LLM-Based Agents", {
    x: 0.7, y: 3.6, w: 5.8, h: 0.8,
    fontSize: 16, fontFace: "Calibri",
    color: "AAAAAA", bold: false,
    align: "left", valign: "top",
    lineSpacingMultiple: 1.3
  });

  // Source
  slide.addText("arxiv.org/abs/2504.03553", {
    x: 0.7, y: 4.8, w: 5.8, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "666666", bold: false,
    align: "left", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a0a0a", secondary: "0070F3", accent: "D4AF37", light: "f5f5f5", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

