const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'comparison',
  index: 2,
  title: "Current Agent Training Uses 'Flood Irrigation'"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Current Agent Training Uses 'Flood Irrigation'", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 30, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left"
  });

  // Subtitle
  slide.addText("Indiscriminate Knowledge Injection Hurts Efficiency", {
    x: 0.5, y: 0.9, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // Three paradigm cards
  const cardY = 1.6;
  const cardH = 2.5;
  const cardW = 2.8;
  const gap = 0.3;
  const startX = 0.5;

  const paradigms = [
    {
      title: "Trajectory Imitation",
      method: "e.g., ReAct",
      desc: "Blindly copies gold trajectories without assessing whether the agent can act correctly on its own.",
      icon: "01",
      accentColor: theme.secondary
    },
    {
      title: "Trial-and-Error",
      method: "e.g., Reflexion",
      desc: "Reflexively applies self-reflection at every step, even when the agent already knows the right action.",
      icon: "02",
      accentColor: "E07020"
    },
    {
      title: "Knowledge-Augmented",
      method: "e.g., KnowAgent, WKM",
      desc: "Injects domain knowledge at every step regardless of situational need, creating unnecessary cost.",
      icon: "03",
      accentColor: theme.accent
    }
  ];

  paradigms.forEach((p, i) => {
    const x = startX + i * (cardW + gap);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: cardY, w: cardW, h: cardH,
      fill: { color: theme.light },
      rectRadius: 0.03
    });

    // Top accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: cardY, w: cardW, h: 0.06,
      fill: { color: p.accentColor }
    });

    // Number
    slide.addText(p.icon, {
      x: x + 0.15, y: cardY + 0.2, w: 0.5, h: 0.4,
      fontSize: 22, fontFace: "Georgia",
      color: p.accentColor, bold: true, align: "left"
    });

    // Title
    slide.addText(p.title, {
      x: x + 0.15, y: cardY + 0.6, w: cardW - 0.3, h: 0.4,
      fontSize: 16, fontFace: "Georgia",
      color: theme.primary, bold: true, align: "left"
    });

    // Method label
    slide.addText(p.method, {
      x: x + 0.15, y: cardY + 0.95, w: cardW - 0.3, h: 0.3,
      fontSize: 11, fontFace: "Calibri",
      color: "888888", bold: false, align: "left"
    });

    // Description
    slide.addText(p.desc, {
      x: x + 0.15, y: cardY + 1.3, w: cardW - 0.3, h: 1.0,
      fontSize: 12, fontFace: "Calibri",
      color: "444444", bold: false, align: "left", valign: "top",
      lineSpacingMultiple: 1.3
    });
  });

  // Bottom contrast bar
  const bottomY = 4.4;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: bottomY, w: 9.0, h: 0.7,
    fill: { color: theme.primary }
  });

  slide.addText([
    { text: "Humans: ", options: { bold: true, color: theme.accent, fontSize: 13, fontFace: "Calibri" } },
    { text: "Situational self-awareness — know when to act, reflect, or seek help    ", options: { color: "CCCCCC", fontSize: 13, fontFace: "Calibri" } },
    { text: "Agents: ", options: { bold: true, color: "FF6B6B", fontSize: 13, fontFace: "Calibri" } },
    { text: "No metacognitive regulation — all steps receive the same treatment", options: { color: "CCCCCC", fontSize: 13, fontFace: "Calibri" } }
  ], {
    x: 0.7, y: bottomY, w: 8.6, h: 0.7,
    align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a0a0a", secondary: "0070F3", accent: "D4AF37", light: "f5f5f5", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

