const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'process',
  index: 3,
  title: 'Three Situational Thinking Modes'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Three Situational Thinking Modes", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 30, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left"
  });

  // Subtitle
  slide.addText("Decision criteria derived from agent ability at each step", {
    x: 0.5, y: 0.9, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // === Decision tree / flow diagram ===

  // Top node: "Agent at Decision Step"
  const topNodeX = 3.5;
  const topNodeY = 1.55;
  const topNodeW = 3.0;
  const topNodeH = 0.5;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: topNodeX, y: topNodeY, w: topNodeW, h: topNodeH,
    fill: { color: theme.primary },
    rectRadius: 0.03
  });
  slide.addText("Agent at Decision Step", {
    x: topNodeX, y: topNodeY, w: topNodeW, h: topNodeH,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Vertical line from top node down to decision diamond area
  slide.addShape(pres.shapes.LINE, {
    x: 5.0, y: 2.05, w: 0, h: 0.35,
    line: { color: "999999", width: 1.5 }
  });

  // Decision diamond (approximated as rotated rectangle / oval)
  const diamondX = 4.1;
  const diamondY = 2.4;
  const diamondW = 1.8;
  const diamondH = 0.55;
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: diamondX, y: diamondY, w: diamondW, h: diamondH,
    fill: { color: "E8E8E8" },
    line: { color: "999999", width: 1 },
    rectRadius: 0.27
  });
  slide.addText("Predicted = Gold?", {
    x: diamondX, y: diamondY, w: diamondW, h: diamondH,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center", valign: "middle"
  });

  // === Three branches ===
  const branchY = 3.2;

  // LEFT branch: Fast Thinking (Yes)
  const fastX = 0.3;
  const fastW = 2.8;
  const fastH = 2.0;

  // Line from diamond to left
  slide.addShape(pres.shapes.LINE, {
    x: 4.1, y: 2.67, w: -1.3, h: 0.53,
    line: { color: "999999", width: 1.5 }
  });

  // "Yes" label
  slide.addText("YES", {
    x: 3.0, y: 2.7, w: 0.6, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "2E7D32", bold: true, align: "center"
  });

  // Fast Thinking card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: fastX, y: branchY, w: fastW, h: fastH,
    fill: { color: "E8F5E9" },
    rectRadius: 0.03
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: fastX, y: branchY, w: fastW, h: 0.06,
    fill: { color: "2E7D32" }
  });

  slide.addText("FAST THINKING", {
    x: fastX + 0.15, y: branchY + 0.15, w: fastW - 0.3, h: 0.35,
    fontSize: 15, fontFace: "Georgia",
    color: "2E7D32", bold: true, align: "left"
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: fastX + 0.15, y: branchY + 0.5, w: 0.4, h: 0.04,
    fill: { color: "2E7D32" }
  });

  slide.addText([
    { text: "Criterion: ", options: { bold: true, fontSize: 11, fontFace: "Calibri", color: "333333" } },
    { text: "Predicted action matches gold action", options: { fontSize: 11, fontFace: "Calibri", color: "555555" } }
  ], {
    x: fastX + 0.15, y: branchY + 0.65, w: fastW - 0.3, h: 0.35,
    align: "left", valign: "top"
  });
  slide.addText([
    { text: "Action: ", options: { bold: true, fontSize: 11, fontFace: "Calibri", color: "333333" } },
    { text: "Direct correct action with minimal deliberation", options: { fontSize: 11, fontFace: "Calibri", color: "555555" } }
  ], {
    x: fastX + 0.15, y: branchY + 1.1, w: fastW - 0.3, h: 0.35,
    align: "left", valign: "top"
  });
  slide.addText("⚡ No special token needed", {
    x: fastX + 0.15, y: branchY + 1.55, w: fastW - 0.3, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "2E7D32", bold: false, align: "left"
  });

  // MIDDLE branch: Slow Thinking (No, but reflection fixes)
  const slowX = 3.5;
  const slowW = 2.8;

  // Line from diamond down to middle
  slide.addShape(pres.shapes.LINE, {
    x: 5.0, y: 2.95, w: 0, h: 0.25,
    line: { color: "999999", width: 1.5 }
  });

  // "No" label
  slide.addText("NO", {
    x: 5.1, y: 2.95, w: 0.5, h: 0.25,
    fontSize: 10, fontFace: "Calibri",
    color: "B71C1C", bold: true, align: "left"
  });

  // Slow Thinking card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: slowX, y: branchY, w: slowW, h: fastH,
    fill: { color: "FFF3E0" },
    rectRadius: 0.03
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: slowX, y: branchY, w: slowW, h: 0.06,
    fill: { color: "E65100" }
  });

  slide.addText("SLOW THINKING", {
    x: slowX + 0.15, y: branchY + 0.15, w: slowW - 0.3, h: 0.35,
    fontSize: 15, fontFace: "Georgia",
    color: "E65100", bold: true, align: "left"
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: slowX + 0.15, y: branchY + 0.5, w: 0.4, h: 0.04,
    fill: { color: "E65100" }
  });

  slide.addText([
    { text: "Criterion: ", options: { bold: true, fontSize: 11, fontFace: "Calibri", color: "333333" } },
    { text: "Incorrect initially, but self-reflection corrects it", options: { fontSize: 11, fontFace: "Calibri", color: "555555" } }
  ], {
    x: slowX + 0.15, y: branchY + 0.65, w: slowW - 0.3, h: 0.35,
    align: "left", valign: "top"
  });
  slide.addText([
    { text: "Action: ", options: { bold: true, fontSize: 11, fontFace: "Calibri", color: "333333" } },
    { text: "Self-correct through reflection", options: { fontSize: 11, fontFace: "Calibri", color: "555555" } }
  ], {
    x: slowX + 0.15, y: branchY + 1.1, w: slowW - 0.3, h: 0.35,
    align: "left", valign: "top"
  });
  slide.addText("↻ Reflection token triggered", {
    x: slowX + 0.15, y: branchY + 1.55, w: slowW - 0.3, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "E65100", bold: false, align: "left"
  });

  // RIGHT branch: Knowledgeable Thinking
  const knowX = 6.8;
  const knowW = 2.8;

  // Line from diamond to right
  slide.addShape(pres.shapes.LINE, {
    x: 5.9, y: 2.67, w: 1.3, h: 0.53,
    line: { color: "999999", width: 1.5 }
  });

  // "Still No" label
  slide.addText("STILL NO", {
    x: 6.3, y: 2.7, w: 0.9, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.accent, bold: true, align: "left"
  });

  // Knowledgeable Thinking card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: knowX, y: branchY, w: knowW, h: fastH,
    fill: { color: "FFF8E1" },
    rectRadius: 0.03
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: knowX, y: branchY, w: knowW, h: 0.06,
    fill: { color: theme.accent }
  });

  slide.addText("KNOWLEDGEABLE THINKING", {
    x: knowX + 0.15, y: branchY + 0.15, w: knowW - 0.3, h: 0.35,
    fontSize: 15, fontFace: "Georgia",
    color: "8B6914", bold: true, align: "left"
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: knowX + 0.15, y: branchY + 0.5, w: 0.4, h: 0.04,
    fill: { color: theme.accent }
  });

  slide.addText([
    { text: "Criterion: ", options: { bold: true, fontSize: 11, fontFace: "Calibri", color: "333333" } },
    { text: "Cannot produce correct action even after reflection", options: { fontSize: 11, fontFace: "Calibri", color: "555555" } }
  ], {
    x: knowX + 0.15, y: branchY + 0.65, w: knowW - 0.3, h: 0.35,
    align: "left", valign: "top"
  });
  slide.addText([
    { text: "Action: ", options: { bold: true, fontSize: 11, fontFace: "Calibri", color: "333333" } },
    { text: "Consult external knowledge base", options: { fontSize: 11, fontFace: "Calibri", color: "555555" } }
  ], {
    x: knowX + 0.15, y: branchY + 1.1, w: knowW - 0.3, h: 0.35,
    align: "left", valign: "top"
  });
  slide.addText("\u{1F4D6} Knowledge token triggered", {
    x: knowX + 0.15, y: branchY + 1.55, w: knowW - 0.3, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "8B6914", bold: false, align: "left"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a0a0a", secondary: "0070F3", accent: "D4AF37", light: "f5f5f5", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

