const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'timeline',
  index: 4,
  title: 'KnowSelf Framework'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("KnowSelf Framework", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 30, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left"
  });

  slide.addText("Data Construction → Two-Stage Training → Self-Aware Inference", {
    x: 0.5, y: 0.9, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // === Three pipeline steps with arrows ===
  const stepY = 1.6;
  const stepH = 3.5;
  const stepW = 2.8;
  const gap = 0.35;
  const arrowW = 0.3;
  const totalW = 3 * stepW + 2 * arrowW + 2 * gap;
  const startX = (10 - totalW) / 2;

  const steps = [
    {
      num: "01",
      title: "Self-Awareness\nData Construction",
      color: theme.secondary,
      bgColor: "EBF5FF",
      details: [
        "Agent self-explores the environment",
        "Heuristic judgment at each step:",
        "  • Correct → Fast Thinking",
        "  • Reflection fixes → Slow Thinking",
        "  • Needs help → Knowledgeable Thinking",
        "Special tokens inserted to mark each situation"
      ]
    },
    {
      num: "02",
      title: "Two-Stage\nTraining",
      color: "E07020",
      bgColor: "FFF3E8",
      details: [
        "Stage 1: Supervised Fine-Tuning (SFT)",
        "  • Teaches initial self-awareness patterns",
        "  • Learns to associate situations with tokens",
        "Stage 2: Reward-based Policy Optimization (RPO)",
        "  • Refines special token generation",
        "  • Improves situation discrimination"
      ]
    },
    {
      num: "03",
      title: "Self-Aware\nInference",
      color: theme.accent,
      bgColor: "FFF9E8",
      details: [
        "Agent generates special tokens autonomously",
        "Token triggers appropriate behavior:",
        "  • Direct action (no token needed)",
        "  • Reflection token → self-reflection",
        "  • Knowledge token → external retrieval",
        "Selective, efficient knowledge utilization"
      ]
    }
  ];

  steps.forEach((step, i) => {
    const x = startX + i * (stepW + arrowW + gap);

    // Step card
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: stepY, w: stepW, h: stepH,
      fill: { color: step.bgColor },
      rectRadius: 0.03
    });

    // Top accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: stepY, w: stepW, h: 0.06,
      fill: { color: step.color }
    });

    // Step number
    slide.addText(step.num, {
      x: x + 0.15, y: stepY + 0.15, w: 0.6, h: 0.45,
      fontSize: 28, fontFace: "Georgia",
      color: step.color, bold: true, align: "left"
    });

    // Title
    slide.addText(step.title, {
      x: x + 0.15, y: stepY + 0.6, w: stepW - 0.3, h: 0.7,
      fontSize: 15, fontFace: "Georgia",
      color: theme.primary, bold: true, align: "left", valign: "top",
      lineSpacingMultiple: 1.2
    });

    // Divider
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x + 0.15, y: stepY + 1.35, w: stepW - 0.3, h: 0.02,
      fill: { color: "CCCCCC" }
    });

    // Details
    const detailLines = step.details.map((d, di) => ({
      text: d,
      options: {
        fontSize: 10.5,
        fontFace: "Calibri",
        color: d.startsWith("  ") ? "666666" : "333333",
        bold: !d.startsWith("  "),
        breakLine: true
      }
    }));

    slide.addText(detailLines, {
      x: x + 0.15, y: stepY + 1.5, w: stepW - 0.3, h: stepH - 1.7,
      align: "left", valign: "top",
      lineSpacingMultiple: 1.35
    });

    // Arrow between steps
    if (i < 2) {
      const arrowX = x + stepW + gap / 2;
      const arrowY = stepY + stepH / 2 - 0.1;

      slide.addShape(pres.shapes.LINE, {
        x: arrowX, y: arrowY, w: arrowW, h: 0,
        line: { color: "999999", width: 2 }
      });
      // Arrowhead (small triangle approximated by line)
      slide.addShape(pres.shapes.LINE, {
        x: arrowX + arrowW - 0.08, y: arrowY - 0.08, w: 0.08, h: 0.08,
        line: { color: "999999", width: 2 }
      });
      slide.addShape(pres.shapes.LINE, {
        x: arrowX + arrowW - 0.08, y: arrowY + 0.08, w: 0.08, h: -0.08,
        line: { color: "999999", width: 2 }
      });
    }
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a0a0a", secondary: "0070F3", accent: "D4AF37", light: "f5f5f5", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

