const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'comparison',
  index: 5,
  title: 'Qualitative Examples'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("KnowSelf Correctly Heats a Mug and Places a Saltshaker", {
    x: 0.5, y: 0.3, w: 9.2, h: 0.6,
    fontSize: 26, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", fit: "shrink"
  });

  slide.addText("Where baselines fail, KnowSelf applies the right situational thinking mode", {
    x: 0.5, y: 0.9, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // === Two side-by-side example cards ===
  const cardY = 1.5;
  const cardH = 3.5;
  const cardW = 4.3;
  const gap = 0.4;

  // LEFT CARD: "put a hot mug in cabinet"
  const leftX = 0.5;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: cardY, w: cardW, h: cardH,
    fill: { color: theme.light },
    rectRadius: 0.03
  });

  // Task label
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: leftX + 0.15, y: cardY + 0.15, w: 1.8, h: 0.3,
    fill: { color: theme.secondary },
    rectRadius: 0.15
  });
  slide.addText("TASK A", {
    x: leftX + 0.15, y: cardY + 0.15, w: 1.8, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  // Task description
  slide.addText('"Put a hot mug in cabinet"', {
    x: leftX + 0.15, y: cardY + 0.55, w: cardW - 0.3, h: 0.35,
    fontSize: 13, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left"
  });

  // OpenAI-O1 failure
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX + 0.15, y: cardY + 1.0, w: cardW - 0.3, h: 0.02,
    fill: { color: "DDDDDD" }
  });

  slide.addText("OpenAI-O1 (fails)", {
    x: leftX + 0.15, y: cardY + 1.1, w: cardW - 0.3, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: "C62828", bold: true, align: "left"
  });

  slide.addText("Opens microwave, then incorrectly tries\nto take an egg instead of heating the mug", {
    x: leftX + 0.15, y: cardY + 1.4, w: cardW - 0.3, h: 0.55,
    fontSize: 11, fontFace: "Calibri",
    color: "555555", bold: false, align: "left", valign: "top",
    lineSpacingMultiple: 1.3
  });

  // KnowSelf success
  slide.addText("KnowSelf (Llama-8B) — succeeds", {
    x: leftX + 0.15, y: cardY + 2.05, w: cardW - 0.3, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: "2E7D32", bold: true, align: "left"
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: leftX + 0.15, y: cardY + 2.4, w: 1.5, h: 0.3,
    fill: { color: "E65100" },
    rectRadius: 0.15
  });
  slide.addText("Reflection Token", {
    x: leftX + 0.15, y: cardY + 2.4, w: 1.5, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
