const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Key Takeaways'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left"
  });

  slide.addText("Self-Awareness Is the Missing Piece in Agent Planning", {
    x: 0.5, y: 0.9, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.accent, bold: false, align: "left"
  });

  // === Five key findings ===
  const findings = [
    {
      num: "1",
      text: "Indiscriminate knowledge injection is wasteful and suboptimal — 100% knowledge methods underperform selective use",
      accentColor: theme.accent
    },
    {
      num: "2",
      text: "Agents can learn situational self-awareness via special tokens with lightweight heuristic labeling — no expensive human annotation needed",
      accentColor: theme.secondary
    },
    {
      num: "3",
      text: "KnowSelf (Llama-8B) achieves 84.33%, surpassing GPT-4o ReAct (76.12%) and GPT-4o ExpeL (79.85%)",
      accentColor: theme.accent
    },
    {
      num: "4",
      text: "Only 15-26% knowledge usage needed versus 100% for competing methods — dramatic efficiency gain",
      accentColor: theme.secondary
    },
    {
      num: "5",
      text: "The paradigm generalizes across model scales — even Gemma-2B (79.85%) matches GPT-4o ExpeL with KnowSelf",
      accentColor: theme.accent
    }
  ];

  const startY = 1.55;
  const itemH = 0.65;
  const itemGap = 0.1;

  findings.forEach((f, i) => {
    const y = startY + i * (itemH + itemGap);

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.6, y: y + 0.05, w: 0.4, h: 0.4,
      fill: { color: f.accentColor }
    });
    slide.addText(f.num, {
      x: 0.6, y: y + 0.05, w: 0.4, h: 0.4,
      fontSize: 16, fontFace: "Georgia",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Text
    slide.addText(f.text, {
      x: 1.2, y: y, w: 7.8, h: itemH,
      fontSize: 13, fontFace: "Calibri",
      color: "DDDDDD", bold: false, align: "left", valign: "middle",
      lineSpacingMultiple: 1.2
    });

    // Subtle divider
    if (i < findings.length - 1) {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 1.2, y: y + itemH + 0.02, w: 7.8, h: 0.01,
        fill: { color: "333333" }
      });
    }
  });

  // Bottom reference
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.0, w: 9.0, h: 0.01,
    fill: { color: "444444" }
  });

  slide.addText("Source: arxiv.org/abs/2504.03553", {
    x: 0.5, y: 5.05, w: 5, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "888888", bold: false, align: "left"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a0a0a", secondary: "0070F3", accent: "D4AF37", light: "f5f5f5", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

