const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'data-visualization',
  index: 7,
  title: 'Efficiency Advantage'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Minimal Knowledge, Maximum Impact", {
    x: 0.5, y: 0.3, w: 9, h: 0.55,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left"
  });

  slide.addText("KnowSelf's efficiency advantage over full-knowledge methods", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // === Grouped bar chart: Knowledge Usage % vs Accuracy % ===
  const chartData = [
    {
      name: "Knowledge Usage %",
      labels: ["KnowSelf\nLlama-8B", "KnowSelf\nGemma-2B", "ExpeL\nGPT-4o", "KnowAgent\nLlama-8B", "WKM\nLlama-8B", "WKM\nGemma-2B"],
      values: [15.01, 26.41, 100, 100, 100, 100]
    },
    {
      name: "Accuracy (All %)",
      labels: ["KnowSelf\nLlama-8B", "KnowSelf\nGemma-2B", "ExpeL\nGPT-4o", "KnowAgent\nLlama-8B", "WKM\nLlama-8B", "WKM\nGemma-2B"],
      values: [84.33, 79.85, 79.85, 75.37, 77.61, 76.12]
    }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.3, y: 1.35, w: 6.2, h: 3.2,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [theme.accent, theme.secondary],
    showTitle: false,
    catAxisLabelColor: "444444",
    catAxisLabelFontSize: 8,
    valAxisLabelColor: "888888",
    valAxisLabelFontSize: 9,
    valAxisMaxVal: 110,
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: "333333",
    dataLabelFontSize: 8,
    showLegend: true,
    legendPos: "b",
    legendColor: "444444",
    legendFontSize: 9,
    chartArea: { fill: { color: "FFFFFF" } }
  });

  // === Right side: Key insights ===
  const rightX = 6.7;

  // Insight 1: Efficiency callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.35, w: 3.0, h: 1.1,
    fill: { color: theme.light },
    rectRadius: 0.03
  });

  slide.addText("15%", {
    x: rightX + 0.15, y: 1.4, w: 1.2, h: 0.55,
    fontSize: 36, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left", valign: "middle"
  });
  slide.addText("Knowledge needed\nfor best Llama-8B result", {
    x: rightX + 0.15, y: 1.9, w: 2.7, h: 0.45,
    fontSize: 10, fontFace: "Calibri",
    color: "555555", bold: false, align: "left", valign: "top",
    lineSpacingMultiple: 1.2
  });

  // Insight 2: 100% vs 15%
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 2.6, w: 3.0, h: 1.1,
    fill: { color: "FFF0F0" },
    rectRadius: 0.03
  });

  slide.addText("6-7x", {
    x: rightX + 0.15, y: 2.65, w: 1.2, h: 0.55,
    fontSize: 36, fontFace: "Georgia",
    color: "C62828", bold: true, align: "left", valign: "middle"
  });
  slide.addText("More knowledge used by\ncompeting methods, yet lower accuracy", {
    x: rightX + 0.15, y: 3.15, w: 2.7, h: 0.45,
    fontSize: 10, fontFace: "Calibri",
    color: "666666", bold: false, align: "left", valign: "top",
    lineSpacingMultiple: 1.2
  });

  // Insight 3: Scaling
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 3.85, w: 3.0, h: 1.0,
    fill: { color: theme.light },
    rectRadius: 0.03
  });

  slide.addText("26%", {
    x: rightX + 0.15, y: 3.9, w: 1.2, h: 0.55,
    fontSize: 36, fontFace: "Georgia",
    color: theme.secondary, bold: true, align: "left", valign: "middle"
  });
  slide.addText("Knowledge for Gemma-2B\nstill matches GPT-4o ExpeL", {
    x: rightX + 0.15, y: 4.4, w: 2.7, h: 0.4,
    fontSize: 10, fontFace: "Calibri",
    color: "555555", bold: false, align: "left", valign: "top",
    lineSpacingMultiple: 1.2
  });

  // Bottom insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.95, w: 9.0, h: 0.4,
    fill: { color: theme.primary }
  });

  slide.addText("Selective knowledge use (15-26%) consistently outperforms indiscriminate injection (100%) across all model scales", {
    x: 0.65, y: 4.95, w: 8.7, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: theme.accent, bold: true, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a0a0a", secondary: "0070F3", accent: "D4AF37", light: "f5f5f5", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

